WITH recent_subscriptions AS (SELECT * FROM subscriptions WHERE monthly_fee BETWEEN 100 AND 190), agg AS (SELECT MONTH(end_date) AS end_month, SUM(monthly_fee) AS total_monthly_fee, ROUND((100 * SUM(CASE WHEN status = 'CANCELLED' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_cancelled FROM recent_subscriptions GROUP BY MONTH(end_date)) SELECT * FROM agg WHERE pct_cancelled >= 45 ORDER BY total_monthly_fee DESC
